window.BIOLEARN_FACT_BANK = {"Cell Biology":[{"q":"What is the basic structural and functional unit of life?","options":["Cell","Tissue","Organ","Organ system"],"answer":0,"explanation":"Cells are the smallest units that carry out the functions associated with life."},{"q":"Which structure controls movement of many substances into and out of a cell?","options":["Cell membrane","Cell wall","Nucleolus","Chromosome"],"answer":0,"explanation":"The selectively permeable cell membrane regulates exchange between the cell and its surroundings."},{"q":"Which organelle is the main site of aerobic respiration in eukaryotic cells?","options":["Mitochondrion","Ribosome","Golgi apparatus","Vacuole"],"answer":0,"explanation":"Mitochondria generate much of the ATP during aerobic respiration."},{"q":"Which structure contains most of the genetic material in a typical eukaryotic cell?","options":["Nucleus","Cell wall","Lysosome","Centriole"],"answer":0,"explanation":"The nucleus contains chromosomes made of DNA and associated proteins."},{"q":"What is osmosis?","options":["Net movement of water through a selectively permeable membrane","Movement of solute from low to high concentration using ATP","Breakdown of glucose with oxygen","Engulfing a large particle"],"answer":0,"explanation":"Osmosis is the net movement of water across a selectively permeable membrane down its water-potential gradient."},{"q":"Which process can move substances against a concentration gradient using energy?","options":["Active transport","Simple diffusion","Osmosis","Filtration only"],"answer":0,"explanation":"Active transport uses energy, often from ATP, to move substances against a gradient."},{"q":"What is the function of ribosomes?","options":["Protein synthesis","Lipid storage only","Photosynthesis","DNA packaging only"],"answer":0,"explanation":"Ribosomes translate messenger RNA to assemble amino acids into polypeptides."},{"q":"Which feature is typical of plant cells but absent from animal cells?","options":["Cellulose cell wall","Cell membrane","Cytoplasm","Mitochondria"],"answer":0,"explanation":"Typical plant cells have a cellulose cell wall; animal cells do not."},{"q":"What is the function of chloroplasts in green plant cells?","options":["Photosynthesis","Aerobic respiration only","Protein digestion","Waste filtration"],"answer":0,"explanation":"Chloroplasts contain chlorophyll and the machinery for photosynthesis."},{"q":"Why are cells usually small?","options":["Small cells have a relatively high surface-area-to-volume ratio","Small cells never need energy","Large cells cannot contain DNA","Small cells have no membrane"],"answer":0,"explanation":"A high surface-area-to-volume ratio supports exchange with the environment."}],"Genetics and Evolution":[{"q":"What is a gene?","options":["A DNA sequence contributing to a functional product or inherited trait","A complete organ system","A type of cell membrane","A food-storage organelle"],"answer":0,"explanation":"Genes are DNA sequences that encode functional products and can influence inherited characteristics."},{"q":"Where are genes arranged in eukaryotic cells?","options":["On chromosomes","Inside cell walls","On ribosomes only","In the vacuole only"],"answer":0,"explanation":"Chromosomes contain DNA and proteins; genes occupy specific positions along DNA."},{"q":"What is an allele?","options":["An alternative form of a gene","A type of tissue","A complete chromosome set only","An environmental factor"],"answer":0,"explanation":"Alleles are different versions of the same gene at a locus."},{"q":"What is genotype?","options":["The genetic constitution of an organism","Only the visible appearance","The organism’s habitat","The total number of species in an area"],"answer":0,"explanation":"Genotype describes the alleles or genetic make-up an organism carries."},{"q":"What is phenotype?","options":["Observable characteristics produced by genotype and environment","Only DNA sequence","A cell organelle","A method of classification"],"answer":0,"explanation":"Phenotype includes observable traits shaped by genes and environmental influences."},{"q":"What does meiosis normally produce in animals?","options":["Haploid cells with half the chromosome number","Identical diploid body cells only","Four identical organs","Cells with no genetic material"],"answer":0,"explanation":"Meiosis reduces chromosome number and contributes to genetic variation in gametes."},{"q":"What is a mutation?","options":["A change in genetic material","Any temporary change in behaviour","A type of ecosystem","The joining of two organs"],"answer":0,"explanation":"Mutations are changes in DNA sequence or, more broadly, genetic material."},{"q":"Natural selection occurs when…","options":["Heritable differences affect survival and reproductive success","All individuals reproduce equally in every environment","Organisms choose mutations they need","Traits acquired during life always pass to offspring"],"answer":0,"explanation":"Natural selection changes trait frequencies when heritable variation affects reproductive success."},{"q":"What is a dominant allele in a simple Mendelian model?","options":["An allele expressed in a heterozygote","An allele always more common in a population","An allele that cannot mutate","An allele found only in males"],"answer":0,"explanation":"A dominant allele affects the phenotype in a heterozygote under the stated inheritance model."},{"q":"Why can sexual reproduction increase variation?","options":["Meiosis and fertilisation combine genetic material in new combinations","It always creates exact clones","It removes all mutations","It prevents recombination"],"answer":0,"explanation":"Meiosis and random fertilisation can produce new combinations of alleles."}],"Ecology and Conservation":[{"q":"What is a habitat?","options":["The place where an organism lives","The role an organism performs only","All ecosystems on Earth","A group of organs"],"answer":0,"explanation":"A habitat is the environment in which an organism normally lives."},{"q":"Which is an abiotic factor?","options":["Light intensity","Grass","Fungi","Predatory fish"],"answer":0,"explanation":"Abiotic factors are non-living conditions such as light, temperature, water and pH."},{"q":"What is a population?","options":["Members of one species living in an area at a given time","All species on Earth","Only non-living factors","All food chains in a biome"],"answer":0,"explanation":"A population consists of individuals of the same species in a defined area and time."},{"q":"What does a food-chain arrow usually show?","options":["Direction of energy transfer","Direction animals always move","The age of each organism","The size of each population"],"answer":0,"explanation":"Arrows point from the organism being eaten toward the consumer, showing energy transfer."},{"q":"What is the main role of decomposers?","options":["Break down dead material and recycle nutrients","Produce sunlight","Stop all energy loss","Make rocks reproduce"],"answer":0,"explanation":"Decomposers release nutrients from dead organisms and wastes."},{"q":"Which process removes carbon dioxide from the atmosphere?","options":["Photosynthesis","Combustion","Respiration","Decomposition alone"],"answer":0,"explanation":"Photosynthetic organisms use carbon dioxide to build organic molecules."},{"q":"What is biodiversity?","options":["Variety of life at genetic, species and ecosystem levels","Only the number of trees in one garden","The amount of rainfall only","A type of pollution"],"answer":0,"explanation":"Biodiversity includes variation within species, between species and among ecosystems."},{"q":"Which is an example of in-situ conservation?","options":["Protecting organisms in their natural habitat","Keeping seeds only in a laboratory","Storing tissue in a freezer only","Displaying specimens in a museum"],"answer":0,"explanation":"In-situ conservation protects species in their natural ecosystems."},{"q":"What is eutrophication commonly associated with?","options":["Excess nutrients entering water and causing algal growth","A complete absence of nutrients in every soil","An increase in oxygen caused by no algae","The formation of chromosomes"],"answer":0,"explanation":"Nutrient enrichment can cause algal blooms and oxygen depletion as biomass decomposes."},{"q":"What does carrying capacity mean?","options":["Population size an environment can sustain over time under given conditions","The number of genes in a cell","The speed of a predator","The amount of oxygen in one leaf"],"answer":0,"explanation":"Carrying capacity depends on available resources and environmental limits."}],"Plant Biology":[{"q":"What is photosynthesis?","options":["Using light energy to make organic substances from carbon dioxide and water","Breaking down glucose to release energy only","Absorbing minerals without water","Moving pollen to a stigma only"],"answer":0,"explanation":"Photosynthesis converts light energy into chemical energy stored in organic compounds."},{"q":"Which pigment absorbs light for photosynthesis?","options":["Chlorophyll","Haemoglobin","Melanin","Keratin"],"answer":0,"explanation":"Chlorophyll absorbs light energy in photosynthetic membranes."},{"q":"Which tissue transports water and mineral ions from roots?","options":["Xylem","Phloem","Epidermis only","Cortex only"],"answer":0,"explanation":"Xylem conducts water and mineral ions and also contributes structural support."},{"q":"Which tissue transports sugars around a plant?","options":["Phloem","Xylem","Cuticle","Root cap only"],"answer":0,"explanation":"Phloem translocates sugars and other organic substances from sources to sinks."},{"q":"What is transpiration?","options":["Loss of water vapour from aerial parts of a plant","Absorption of minerals by roots only","Fusion of gametes","Release of pollen"],"answer":0,"explanation":"Transpiration is the loss of water vapour, mainly through stomata in leaves."},{"q":"Where does pollen usually land during pollination in flowering plants?","options":["Stigma","Ovary wall","Root hair","Anther filament"],"answer":0,"explanation":"The stigma receives pollen during pollination."},{"q":"What is fertilisation in flowering plants?","options":["Fusion of male and female gamete nuclei","The movement of pollen alone","The opening of a seed coat","The loss of water from leaves"],"answer":0,"explanation":"Fertilisation involves fusion of gamete nuclei; flowering plants have double fertilisation."},{"q":"Which condition is generally required for most seeds to germinate?","options":["Water, oxygen and a suitable temperature","Bright light in every species","Fertiliser only","Carbon dioxide without water"],"answer":0,"explanation":"Most seeds require water, oxygen and a suitable temperature; light requirements vary by species."},{"q":"What is the main function of root hairs?","options":["Increase surface area for absorption","Produce pollen","Carry out all photosynthesis","Protect flowers from pollinators"],"answer":0,"explanation":"Root hairs increase the surface area available for water and mineral uptake."},{"q":"Why do stomata open and close?","options":["To regulate gas exchange and water loss","To make roots grow toward gravity only","To digest soil","To produce seeds directly"],"answer":0,"explanation":"Guard cells regulate stomatal opening, balancing carbon dioxide uptake with water conservation."}],"Human and Animal Biology":[{"q":"What is the main function of red blood cells in humans?","options":["Transport oxygen using haemoglobin","Produce digestive enzymes","Filter urine","Transmit nerve impulses"],"answer":0,"explanation":"Haemoglobin in red blood cells binds and transports oxygen."},{"q":"Where does most absorption of digested nutrients occur in humans?","options":["Small intestine","Oesophagus","Trachea","Urinary bladder"],"answer":0,"explanation":"The small intestine has villi and microvilli that provide a large absorptive surface."},{"q":"What is the main function of the kidneys?","options":["Filter blood and regulate water and ion balance","Pump blood around the body","Exchange gases in alveoli","Produce bile for fat digestion"],"answer":0,"explanation":"Kidneys filter blood, remove wastes and regulate fluid, electrolyte and acid-base balance."},{"q":"Where does gas exchange occur in human lungs?","options":["Alveoli","Bronchi only","Nasal cavity only","Diaphragm"],"answer":0,"explanation":"Thin alveolar walls and dense capillary networks support diffusion of oxygen and carbon dioxide."},{"q":"What is a hormone?","options":["A chemical messenger carried to target cells","A type of bone","A digestive food group","A pathogen"],"answer":0,"explanation":"Hormones are signalling molecules that act on cells with appropriate receptors."},{"q":"What is the role of the nervous system?","options":["Receive information and coordinate rapid responses","Digest all food outside the body","Transport water in plants","Make antibodies only"],"answer":0,"explanation":"Neurons and neural circuits transmit information and coordinate responses."},{"q":"What is vaccination designed to do?","options":["Prepare immune memory against a specific pathogen or antigen","Treat every infection instantly","Replace all white blood cells","Prevent all diseases without exception"],"answer":0,"explanation":"Vaccines stimulate adaptive immune responses and immune memory; protection varies by vaccine and disease."},{"q":"What is peristalsis?","options":["Wave-like muscular contractions that move contents through the gut","Filtering blood in the kidney","Gas exchange in the lungs","Formation of red blood cells"],"answer":0,"explanation":"Peristaltic contractions propel food along the digestive tract."},{"q":"What is excretion?","options":["Removal of metabolic waste products","Removal of undigested food only","Intake of nutrients","Production of offspring"],"answer":0,"explanation":"Excretion removes wastes produced by metabolism, such as urea and carbon dioxide."},{"q":"What is the function of a synapse?","options":["Enable signalling between neurons or a neuron and target cell","Join bones permanently","Absorb water in the colon only","Produce bile"],"answer":0,"explanation":"Synapses transmit signals chemically or electrically between cells."}],"Microbiology":[{"q":"Which statement about bacteria is correct?","options":["They are prokaryotic organisms","They always have a membrane-bound nucleus","All cause disease","They are multicellular animals"],"answer":0,"explanation":"Bacteria are prokaryotes and lack a membrane-bound nucleus; many are harmless or beneficial."},{"q":"Viruses reproduce by…","options":["Using a host cell’s machinery","Dividing independently like typical bacteria","Photosynthesising","Making their own ribosomes"],"answer":0,"explanation":"Viruses require host-cell machinery to produce new virus particles."},{"q":"What is an antibiotic generally used to treat?","options":["Susceptible bacterial infections","All viral infections","Every genetic disorder","Nutrient deficiency"],"answer":0,"explanation":"Antibiotics target bacteria and do not treat viral infections such as the common cold."},{"q":"What is aseptic technique intended to reduce?","options":["Unwanted contamination","All chemical reactions","The need for handwashing","The size of cells"],"answer":0,"explanation":"Aseptic procedures reduce contamination of samples, people and environments."},{"q":"What is a pathogen?","options":["An organism or agent that can cause disease","Any beneficial nutrient","A type of microscope","A body organ"],"answer":0,"explanation":"Pathogens include disease-causing bacteria, viruses, fungi, protozoa and other agents."},{"q":"Why is handwashing important in infection control?","options":["It removes many microbes and interrupts transmission","It sterilises the entire environment permanently","It replaces vaccination","It kills every pathogen in every situation"],"answer":0,"explanation":"Proper handwashing reduces microbial load and the spread of many infectious agents."},{"q":"What is fermentation commonly used for in food production?","options":["Microbial conversion of substrates into products such as acids or alcohols","Removal of all microbes by filtration only","Production of light in chloroplasts","Changing DNA into bone"],"answer":0,"explanation":"Microorganisms carry out fermentation processes used in foods such as yoghurt and bread."},{"q":"What is a culture medium?","options":["Material supplying nutrients for growing microorganisms","A lens in a microscope","A method of classifying plants only","A type of antibody"],"answer":0,"explanation":"Culture media provide nutrients and conditions for cultivating selected microorganisms."},{"q":"What does antibiotic resistance mean?","options":["Bacteria survive or grow despite an antibiotic that would normally inhibit them","The human body becomes resistant to all diseases","Viruses become bacteria","Antibiotics become nutrients"],"answer":0,"explanation":"Resistance is a microbial trait that reduces susceptibility to an antimicrobial drug."},{"q":"Why should laboratory cultures be handled carefully?","options":["Some microbes may be harmful and can spread through contamination","All microbes are harmless","Cultures cannot multiply","Safety rules reduce accuracy"],"answer":0,"explanation":"Appropriate containment, hygiene and disposal reduce exposure and environmental release."}],"Biochemistry":[{"q":"Which elements are found in carbohydrates?","options":["Carbon, hydrogen and oxygen","Only nitrogen and sulphur","Sodium and chlorine only","Iron and calcium only"],"answer":0,"explanation":"Carbohydrates are organic molecules commonly containing carbon, hydrogen and oxygen."},{"q":"What is the main role of enzymes?","options":["Catalyse biochemical reactions","Store all genetic information","Form every cell wall","Stop all metabolism"],"answer":0,"explanation":"Enzymes lower activation energy and increase reaction rates without being consumed overall."},{"q":"What happens to most enzymes at excessively high temperatures?","options":["Their structure may denature and activity fall","They always become more active without limit","They turn into DNA","They permanently gain new active sites"],"answer":0,"explanation":"High temperature can disrupt the structure of enzymes and alter their active sites."},{"q":"Which molecule stores hereditary information in most organisms?","options":["DNA","Starch","Triglyceride","Cellulose"],"answer":0,"explanation":"DNA stores genetic information in most cellular organisms."},{"q":"What is ATP commonly described as?","options":["A readily usable energy-transfer molecule in cells","A structural carbohydrate in plants","A digestive organ","A type of pathogen"],"answer":0,"explanation":"ATP transfers energy to many cellular processes through phosphate-group reactions."},{"q":"Which nutrient is especially important for building and repairing tissues?","options":["Protein","Water only","Mineral salts only","Dietary fibre only"],"answer":0,"explanation":"Proteins provide amino acids used in growth, repair and synthesis of enzymes and other molecules."},{"q":"What is a lipid?","options":["A diverse group of largely hydrophobic molecules including fats and oils","A type of chromosome","A water-soluble mineral only","A cell organelle"],"answer":0,"explanation":"Lipids include triglycerides, phospholipids and steroids and have roles in energy storage and membranes."},{"q":"What is the role of nucleic acids?","options":["Store, transmit or help express genetic information","Carry oxygen in red blood cells only","Form bones exclusively","Digest fats in the stomach"],"answer":0,"explanation":"DNA and RNA are nucleic acids involved in genetic information storage and expression."},{"q":"What is hydrolysis?","options":["Breaking a chemical bond using water","Joining molecules by removing water only","Movement of water through a membrane","Production of ATP only"],"answer":0,"explanation":"Hydrolysis uses water to split a chemical bond."},{"q":"Why does pH affect enzyme activity?","options":["It can change charges and shape around the active site","It changes the organism’s species name","It removes all substrates instantly","It has no effect on proteins"],"answer":0,"explanation":"pH affects ionisation of amino-acid groups and can alter enzyme structure and activity."}],"Practical Biology":[{"q":"What is the independent variable in an experiment?","options":["The factor deliberately changed by the investigator","The outcome measured","A factor kept constant","A result written after the experiment"],"answer":0,"explanation":"The independent variable is the factor deliberately manipulated to test its effect."},{"q":"What is the dependent variable?","options":["The outcome measured in response to a change","The factor deliberately changed","A factor never measured","The title of the experiment"],"answer":0,"explanation":"The dependent variable is the measured outcome."},{"q":"Why should control variables be kept constant?","options":["To make comparisons fairer by reducing alternative explanations","To guarantee the hypothesis is correct","To prevent data collection","To make results impossible to repeat"],"answer":0,"explanation":"Controlling relevant variables helps isolate the effect of the independent variable."},{"q":"Why repeat measurements or use replicates?","options":["To assess variability and improve confidence in results","To guarantee identical readings","To remove the need for methods","To prove every hypothesis"],"answer":0,"explanation":"Repeats help reveal variation, anomalies and the reliability of an observed pattern."},{"q":"What should a biological drawing usually include?","options":["Clear single lines, appropriate labels and a suitable title","Shading and artistic decoration everywhere","Unlabelled parts only","Invented structures not observed"],"answer":0,"explanation":"Scientific drawings should communicate observed structure clearly and accurately."},{"q":"What is a hypothesis?","options":["A testable proposed explanation or prediction","A result that cannot be checked","A list of equipment only","A conclusion written before data exist"],"answer":0,"explanation":"A hypothesis is a proposed explanation that can be tested against evidence."},{"q":"Which graph is usually suitable for showing change over a continuous variable?","options":["Line graph","Pie chart only","Unordered list","Venn diagram only"],"answer":0,"explanation":"A line graph is commonly used to show trends across continuous values."},{"q":"What is an observation?","options":["Information recorded using senses or instruments","An explanation that must be true","A guess without evidence","A variable that is never measured"],"answer":0,"explanation":"Observations are recorded evidence; interpretations or inferences explain what the evidence may mean."},{"q":"Why include units in a measurement?","options":["They show the scale and quantity being reported","They make values less comparable","They replace the numerical value","They guarantee accuracy"],"answer":0,"explanation":"Units identify the measurement scale, such as centimetres, seconds or grams."},{"q":"What should a conclusion do?","options":["Answer the research question using the results and note limitations","Ignore results that disagree with expectations","Claim proof from one observation in every case","Invent missing data"],"answer":0,"explanation":"A sound conclusion links claims to evidence and recognises limits of the method."}],"Foundational Biology":[{"q":"Which is a characteristic shared by living organisms?","options":["They carry out life processes","They are all able to walk","They all make their own food","They all have a backbone"],"answer":0,"explanation":"Living organisms perform life processes, although the form of each process varies among organisms."},{"q":"What is a balanced diet?","options":["A diet providing needed nutrients in suitable amounts for a person","A diet containing only carbohydrates","The same meal for every person","A diet with no water"],"answer":0,"explanation":"Nutrient needs vary with age, activity, health and other factors."},{"q":"Why is clean water important to health?","options":["It supports body processes and reduces water-borne disease risk when safe","It replaces all nutrients","It prevents every infection","It has no role in the body"],"answer":0,"explanation":"Water is essential for transport, temperature regulation and many reactions; safe water reduces some infection risks."},{"q":"What is a habitat?","options":["The place an organism normally lives","A type of cell","The name of a food nutrient","A method of measurement"],"answer":0,"explanation":"A habitat is the place where an organism lives and obtains resources."},{"q":"What is a food chain?","options":["A sequence showing feeding relationships and energy transfer","A list of minerals in soil","A classification key only","A set of organs"],"answer":0,"explanation":"Food chains show who eats whom and the direction of energy transfer."},{"q":"Why is personal hygiene important?","options":["It helps reduce transmission of infectious agents","It removes the need for safe food","It prevents every illness","It replaces medical treatment"],"answer":0,"explanation":"Hygiene practices interrupt some routes by which pathogens spread."},{"q":"What is classification in biology?","options":["Grouping organisms using shared characteristics and relationships","Measuring rainfall only","A form of digestion","The movement of blood"],"answer":0,"explanation":"Classification organises biodiversity and supports identification and communication."},{"q":"What is a microscope used for?","options":["Magnifying small structures that cannot be seen clearly unaided","Measuring every organism’s mass directly","Growing plants without light","Separating DNA by itself"],"answer":0,"explanation":"Microscopes magnify and resolve details of small specimens."},{"q":"What is adaptation?","options":["An inherited feature that can improve survival or reproduction in an environment","A choice made consciously by every organism","A temporary injury","A synonym for habitat"],"answer":0,"explanation":"Adaptations are inherited traits shaped by evolution that can improve reproductive success in particular conditions."},{"q":"What is conservation?","options":["Protecting biodiversity and using natural resources sustainably","Removing every organism from nature","Increasing pollution","Preventing all ecological change"],"answer":0,"explanation":"Conservation aims to maintain biodiversity, ecosystem functions and sustainable use of resources."}],"General Biology":[{"q":"What is the purpose of biological classification?","options":["To organise organisms and communicate their relationships","To prove all organisms are identical","To replace observation","To describe only non-living matter"],"answer":0,"explanation":"Classification makes biodiversity easier to study and communicate."},{"q":"What is homeostasis?","options":["Regulation of internal conditions within suitable limits","A type of cell division","The transfer of pollen","A method of naming species"],"answer":0,"explanation":"Homeostasis keeps internal variables within ranges compatible with normal function."},{"q":"What is metabolism?","options":["The sum of chemical reactions in an organism","Only movement of an animal","A form of classification","The number of species in a habitat"],"answer":0,"explanation":"Metabolism includes anabolic and catabolic reactions."},{"q":"Why is variation important to natural selection?","options":["Heritable differences can lead to different reproductive success","Variation makes all individuals identical","Variation prevents inheritance","Only acquired traits matter in evolution"],"answer":0,"explanation":"Natural selection acts on heritable variation when it affects survival or reproduction."},{"q":"What is an ecosystem?","options":["Organisms interacting with each other and their physical environment","Only one organism","Only soil without living things","A single organ in an animal"],"answer":0,"explanation":"An ecosystem includes communities and abiotic surroundings linked by interactions and flows of energy and matter."},{"q":"What is a scientific theory?","options":["A well-supported explanatory framework based on extensive evidence","A casual guess with no evidence","A single measurement","A claim that can never be revised"],"answer":0,"explanation":"Scientific theories explain broad patterns and are supported by multiple lines of evidence."},{"q":"What is a control group used for?","options":["Providing a comparison for evaluating an intervention or condition","Guaranteeing a desired outcome","Replacing the experimental group","Removing the need for replication"],"answer":0,"explanation":"A suitable control helps interpret whether observed effects are associated with the tested factor."},{"q":"What is a limiting factor in ecology?","options":["A factor that restricts population growth or distribution","A factor that always increases population","A chromosome in every cell","A type of enzyme only"],"answer":0,"explanation":"Resources and conditions such as food, water, space, predators and temperature can limit populations."},{"q":"Why is evidence important in biology?","options":["It allows explanations to be evaluated against observations and measurements","It guarantees every conclusion is correct","It replaces the need for methods","It makes hypotheses untestable"],"answer":0,"explanation":"Evidence supports, challenges or refines biological explanations."},{"q":"What is a variable?","options":["A factor that can take different values in a study","A result that never changes","A type of organism","A fixed scientific law"],"answer":0,"explanation":"Variables are measurable or categorical factors that can vary across observations or experimental conditions."}],"Advanced Biology":[{"q":"What is a scientific model used for?","options":["Representing and explaining a system or process that may be complex","Replacing all evidence permanently","Guaranteeing every prediction","Avoiding assumptions"],"answer":0,"explanation":"Models simplify systems so assumptions and predictions can be examined against evidence."},{"q":"Why are experimental methods documented?","options":["To support evaluation, replication and reproducibility","To conceal possible bias","To prevent others checking results","To remove the need for data"],"answer":0,"explanation":"Transparent methods allow others to assess and repeat work."},{"q":"What is a confounding variable?","options":["A factor that can distort the apparent relationship between variables","The outcome measured in every experiment","A unit of mass","A type of microscope"],"answer":0,"explanation":"Confounders can create, exaggerate or obscure associations between variables."},{"q":"What does statistical significance alone not establish?","options":["The size or practical importance of an effect","That a test produced a p-value","That data were analysed","That a sample was observed"],"answer":0,"explanation":"Statistical significance does not by itself measure effect size, practical importance or causal certainty."},{"q":"Why is peer review used?","options":["To obtain expert scrutiny of methods, evidence and interpretation","To guarantee a paper is error-free","To replace replication","To ensure all results are positive"],"answer":0,"explanation":"Peer review provides critique but cannot guarantee that every error or bias is detected."},{"q":"What is a null hypothesis commonly used for?","options":["A statistical statement tested against data","A claim that all organisms are identical","A substitute for sampling","A conclusion that cannot be evaluated"],"answer":0,"explanation":"A null hypothesis provides a reference claim for a statistical test."},{"q":"What is reproducibility?","options":["Obtaining consistent findings when a study or analysis is repeated appropriately","Changing data until the result is expected","Using only one sample ever","Avoiding detailed methods"],"answer":0,"explanation":"Reproducibility depends on transparent methods, data and suitable repetition."},{"q":"Why report limitations?","options":["They clarify uncertainty and the scope of conclusions","They make research invalid automatically","They hide the methods","They guarantee a larger effect"],"answer":0,"explanation":"Limitations help readers judge how broadly findings can be applied."},{"q":"What is a dependent variable in a controlled experiment?","options":["The measured outcome that may respond to the independent variable","The factor deliberately manipulated","A factor that must be ignored","The researcher’s opinion"],"answer":0,"explanation":"The dependent variable is measured to evaluate the effect of the independent variable."},{"q":"What is an ethical research practice?","options":["Report methods and results honestly and protect participants where relevant","Invent missing measurements","Hide adverse findings without explanation","Publish identifiable information without consent"],"answer":0,"explanation":"Research integrity requires honest reporting and appropriate protection of people, animals and environments."}]};
